@org.springframework.modulith.ApplicationModule(
    displayName = "Payment Core",
    allowedDependencies = {"common", "provisioning", "risk", "quota", "adapters"})
package com.shadhinpay.paymentcore;

package com.shadhinpay.paymentcore.usecase;

import com.shadhinpay.common.money.Money;
import java.util.Map;
import java.util.Objects;
import java.util.UUID;

/**
 * Request envelope for {@link InitiatePaymentUseCase}.
 *
 * <p>The {@code idempotencyKey} is required and cooperates with the Redis-backed idempotency store:
 * two requests that share {@code (businessId, idempotencyKey)} resolve to the same {@link
 * PaymentInitiationResult} without producing a second {@code Transaction} row.
 *
 * @param businessId business owning this payment (resolved from API key by the gateway filter)
 * @param amount transaction amount and currency
 * @param vendor MFS vendor identifier (e.g. {@code "BKASH"}); kept as {@code String} to defer enum
 *     coupling to Phase 1
 * @param merchantOrderReference merchant-supplied order id, surfaced back via webhooks
 * @param callbackUrl URL the customer is redirected to after the MFS interaction
 * @param webhookUrl URL the merchant's server is notified at on terminal state changes
 * @param metadata immutable bag of merchant-supplied attributes echoed back on every notification
 * @param idempotencyKey caller-supplied key from the {@code X-Idempotency-Key} header
 */
@SuppressWarnings("PMD.UnusedAssignment")
public record InitiatePaymentRequest(
    UUID businessId,
    Money amount,
    String vendor,
    String merchantOrderReference,
    String callbackUrl,
    String webhookUrl,
    Map<String, String> metadata,
    String idempotencyKey) {

  public InitiatePaymentRequest {
    Objects.requireNonNull(businessId, "businessId must not be null");
    Objects.requireNonNull(amount, "amount must not be null");
    Objects.requireNonNull(vendor, "vendor must not be null");
    Objects.requireNonNull(merchantOrderReference, "merchantOrderReference must not be null");
    Objects.requireNonNull(callbackUrl, "callbackUrl must not be null");
    Objects.requireNonNull(webhookUrl, "webhookUrl must not be null");
    Objects.requireNonNull(idempotencyKey, "idempotencyKey must not be null");
    metadata = metadata == null ? Map.of() : Map.copyOf(metadata);
  }
}

package com.shadhinpay.paymentcore.usecase;

/**
 * Initiates a payment: validates idempotency, runs pre-flight checks (provisioning/quota/risk),
 * persists the {@code Transaction}, dispatches to the MFS adapter, and returns the redirect URL.
 *
 * <p><b>Caller:</b> the public REST controller in {@code application} for direct merchant API
 * calls, and the {@code invoice} module when a customer pays a hosted invoice.
 *
 * <p><b>Guarantees:</b>
 *
 * <ul>
 *   <li><b>Idempotent</b> on {@code (businessId, idempotencyKey)}: a duplicate request returns the
 *       original {@link PaymentInitiationResult} without producing a second {@code Transaction}
 *       row.
 *   <li>Pre-flight ordering: provisioning lookup → quota reservation (partner mode only) → risk
 *       evaluation → adapter dispatch. A risk {@code BLOCK} short-circuits before any MFS call.
 *   <li>Reliable delivery: a {@code WebhookOutbox} row is enqueued in the same transaction as the
 *       {@code Transaction} and {@code PaymentInitiatedEvent}.
 * </ul>
 */
public interface InitiatePaymentUseCase {

  /**
   * Initiates a payment for the supplied request.
   *
   * @param request fully-validated {@link InitiatePaymentRequest}
   * @return a {@link PaymentInitiationResult} carrying the new (or replayed) transaction id and
   *     redirect URL; never {@code null}
   */
  PaymentInitiationResult execute(InitiatePaymentRequest request);
}

/**
 * Inbound use-case ports exposed by the Payment Core module.
 *
 * <p>Marked as a Spring Modulith named interface so other modules ({@code invoice}, public REST
 * controllers in {@code application}) may depend on it; sibling internal packages ({@code entity},
 * {@code repository}, {@code mapper}, {@code usecase.impl}) remain off-limits to outside modules.
 */
@org.springframework.modulith.NamedInterface("usecase")
package com.shadhinpay.paymentcore.usecase;

package com.shadhinpay.paymentcore.usecase;

import java.util.Objects;
import java.util.UUID;

/**
 * Result of a successful (or replayed-idempotent) call to {@link InitiatePaymentUseCase}.
 *
 * <p>{@link #redirectUrl} is the URL the merchant must redirect the customer to so they can
 * complete the MFS interaction. {@link #status} is the current {@code Transaction.status} (e.g.
 * {@code "INITIATED"}, {@code "PENDING"}); kept as {@code String} to defer enum coupling to Phase
 * 1.
 *
 * @param transactionId the {@code Transaction.id} created (or matched by idempotency replay)
 * @param redirectUrl URL the merchant must redirect the customer to in order to authorize the
 *     payment with the MFS
 * @param status current {@code Transaction.status} at the moment of return
 */
public record PaymentInitiationResult(UUID transactionId, String redirectUrl, String status) {

  public PaymentInitiationResult {
    Objects.requireNonNull(transactionId, "transactionId must not be null");
    Objects.requireNonNull(redirectUrl, "redirectUrl must not be null");
    Objects.requireNonNull(status, "status must not be null");
  }
}

