    UUID escrowId = UUID.randomUUID();
    UUID revenueId = UUID.randomUUID();
    LedgerAccount escrow = new LedgerAccount(null, LedgerAccountType.ASSET, "ESCROW", 0, "BDT");

"BKASH",
