/**
 * Returns the current cached balance for an owner's account at a given chart-of-accounts code.
 *
 * <p><b>Caller:</b> the {@code settlement} module when computing payouts, the merchant dashboard
 * when displaying balances, and admin tooling for reconciliation.
 *
 * <p><b>Guarantees:</b>
 *
 * <ul>
 *   <li>Reads the {@code LedgerAccount.balance} cached column rather than summing postings — the
 *       module enforces {@code SUM(postings.amount) == account.balance} via a periodic integrity
 *       job (see {@code DOCS/features/ledger/TECH_SPEC.md} §6).
 *   <li>For sharded system accounts (e.g. {@code ESCROW_0..9}), callers should pass the logical
 *       owner; sharding aggregation is the implementation's responsibility.
 *   <li>Throws (rather than returning {@code null}) when no account exists for the {@code (ownerId,
 *       accountCode)} pair.
 * </ul>
 */
public interface GetAccountBalanceUseCase {

  /**
   * Returns the current balance of the account identified by {@code (ownerId, accountCode)}.
   *
   * @param ownerId merchant or system-account owner; never {@code null}
   * @param accountCode chart-of-accounts code (e.g. {@code "MERCHANT_PAYABLE"}, {@code
   *     "PLATFORM_REVENUE"})
   * @return the current balance; never {@code null}
   */
  Money execute(UUID ownerId, String accountCode);
}

package com.shadhinpay.ledger.usecase;

import java.time.Instant;
import java.util.List;
import java.util.Objects;

/**
 * Idempotent request to record a journal entry composed of balanced postings.
 *
 * <p>Consumed by {@link RecordJournalEntryUseCase}. The pair {@code (sourceType, sourceId)} acts as
 * the natural idempotency key — re-submitting the same pair is a no-op even after retries or
 * Modulith event redelivery.
 *
 * @param sourceType the kind of business event being recorded (e.g. {@code "PAYMENT"}, {@code
 *     "REFUND"}, {@code "SETTLEMENT"}, {@code "FEE"}, {@code "ADJUSTMENT"}); kept as {@code String}
 *     to avoid coupling the contract to ledger internals
 * @param sourceId identifier of the source record in the originating module (typically the
 *     transaction id)
 * @param description short human-readable label persisted on the journal entry for audit
 * @param postings list of postings whose signed amounts must sum to zero (defensive copy held)
 * @param occurredAt business-event timestamp; the ledger persists this as {@code
 *     JournalEntry.occurredAt} for reporting purposes
 */
public record JournalEntryRequest(
    String sourceType,
    String sourceId,
    String description,
    List<PostingRequest> postings,
    Instant occurredAt) {

  public JournalEntryRequest {
    Objects.requireNonNull(sourceType, "sourceType must not be null");
    Objects.requireNonNull(sourceId, "sourceId must not be null");
    Objects.requireNonNull(description, "description must not be null");
    Objects.requireNonNull(postings, "postings must not be null");
    Objects.requireNonNull(occurredAt, "occurredAt must not be null");
    if (postings.isEmpty()) {
      throw new IllegalArgumentException("postings must not be empty");
    }
    postings = List.copyOf(postings);
  }
}

/**
 * Inbound use-case ports exposed by the Ledger module.
 *
 * <p>Marked as a Spring Modulith named interface so other modules may depend on it; types in
 * sibling internal packages ({@code entity}, {@code repository}, {@code mapper}, {@code
 * usecase.impl}) remain off-limits to outside modules.
 */
@org.springframework.modulith.NamedInterface("usecase")
package com.shadhinpay.ledger.usecase;

package com.shadhinpay.ledger.usecase;

import com.shadhinpay.common.money.Money;
import java.util.Objects;
import java.util.UUID;

/**
 * Single debit or credit posting against a ledger account.
 *
 * <p>Carried by {@link JournalEntryRequest}. The sum of all {@link #amount} values across a journal
 * must be zero — the ledger module enforces this invariant on {@link RecordJournalEntryUseCase}.
 *
 * @param accountId target {@code LedgerAccount} identifier
 * @param amount signed amount; positive values represent debits, negative values represent credits
 *     (standard accounting convention)
 * @param type explicit debit/credit marker for audit-log clarity; must be consistent with the sign
 *     of {@link #amount}
 */
public record PostingRequest(UUID accountId, Money amount, Type type) {

  /** Explicit debit/credit marker mirroring the sign of {@link PostingRequest#amount()}. */
  public enum Type {
    /** Positive posting (asset increase / liability decrease). */
    DEBIT,
    /** Negative posting (asset decrease / liability increase). */
    CREDIT
  }

  public PostingRequest {
    Objects.requireNonNull(accountId, "accountId must not be null");
    Objects.requireNonNull(amount, "amount must not be null");
    Objects.requireNonNull(type, "type must not be null");
  }
}

package com.shadhinpay.ledger.usecase.impl;

import com.shadhinpay.common.annotation.UseCase;
import com.shadhinpay.common.error.ResourceNotFoundException;
import com.shadhinpay.common.money.Money;
import com.shadhinpay.ledger.entity.LedgerAccount;
import com.shadhinpay.ledger.repository.LedgerAccountRepository;
import com.shadhinpay.ledger.usecase.GetAccountBalanceUseCase;
import java.util.List;
import java.util.UUID;
import lombok.RequiredArgsConstructor;
import org.springframework.transaction.annotation.Transactional;

@UseCase
@RequiredArgsConstructor
public class GetAccountBalanceUseCaseImpl implements GetAccountBalanceUseCase {

  private final LedgerAccountRepository ledgerAccountRepository;

  private static final List<String> SYSTEM_ACCOUNT_CODES =
      List.of("ESCROW", "PLATFORM_REVENUE", "VENDOR_PAYABLE");
  private static final String DEFAULT_CURRENCY = "BDT";

  /**
   * Returns the balance for the given account. Note on read-after-write: for sharded system
   * accounts, summing the balances across shards may be eventually consistent during rapid updates,
   * as updates land on different rows.
   */
  @Override
  @Transactional(readOnly = true)
  public Money execute(UUID ownerId, String accountCode) {
    if (SYSTEM_ACCOUNT_CODES.contains(accountCode)) {
      List<LedgerAccount> shards =
          ledgerAccountRepository.findByCodeAndCurrency(accountCode, DEFAULT_CURRENCY);
      Money total = Money.zero(DEFAULT_CURRENCY);
      for (LedgerAccount shard : shards) {
        total = total.add(shard.getBalance());
      }
      return total;
    } else {
      LedgerAccount account =
          ledgerAccountRepository
              .findByOwnerIdAndCodeAndShardIdAndCurrency(ownerId, accountCode, 0, DEFAULT_CURRENCY)
              .orElseThrow(
                  () ->
                      new ResourceNotFoundException(
                          "Merchant account not found: " + accountCode + " for owner " + ownerId));
      return account.getBalance();
    }
  }
}

