    Money usd = Money.of(1, "USD");

    assertThatThrownBy(() -> bdt.add(usd)).isInstanceOf(IllegalArgumentException.class);
    assertThatThrownBy(() -> bdt.subtract(usd)).isInstanceOf(IllegalArgumentException.class);
