package com.shadhinpay.common.security;

import com.shadhinpay.common.security.AuthenticatedPrincipal.UserType;
import java.util.Optional;
import java.util.UUID;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;

public final class SecurityUtils {

  private SecurityUtils() {}

  public static Optional<AuthenticatedPrincipal> currentPrincipal() {
    Authentication auth = SecurityContextHolder.getContext().getAuthentication();
    if (auth == null || !auth.isAuthenticated()) {
      return Optional.empty();
    }
    Object principal = auth.getPrincipal();
    if (principal instanceof AuthenticatedPrincipal p) {
      return Optional.of(p);
    }
    return Optional.empty();
  }

  public static Optional<UUID> currentUserId() {
    return currentPrincipal().map(AuthenticatedPrincipal::userId);
  }

  public static Optional<UUID> currentMerchantId() {
    return currentPrincipal()
        .filter(p -> p.userType() == UserType.MERCHANT)
        .map(AuthenticatedPrincipal::merchantId);
  }

  public static Optional<UUID> currentBusinessId() {
    return currentPrincipal().map(AuthenticatedPrincipal::businessId);
  }

  public static Optional<UUID> currentAdminId() {
    return currentPrincipal()
        .filter(p -> p.userType() == UserType.ADMIN)
        .map(AuthenticatedPrincipal::userId);
  }
}

package com.shadhinpay.common.observability;

import java.util.Collections;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.env.EnvironmentPostProcessor;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.env.ConfigurableEnvironment;
import org.springframework.core.env.MapPropertySource;
import org.springframework.core.env.PropertySource;

@Configuration
public class LoggingConfig {

  public static final String CONSOLE_PATTERN =
      "%clr(%d{yyyy-MM-dd HH:mm:ss.SSS}){faint} "
          + "%clr(%5p) "
          + "%clr([${spring.application.name:shadhinpay},%X{traceId:-}]){yellow} "
          + "%clr(---){faint} %clr([%15.15t]){faint} "
          + "%clr(%-40.40logger{39}){cyan} %clr(:){faint} %m%n%wEx";

  static final String FILE_PATTERN =
      "%d{yyyy-MM-dd HH:mm:ss.SSS} "
          + "%5p "
          + "[${spring.application.name:shadhinpay},%X{traceId:-}] "
          + "--- [%t] %-40.40logger{39} : %m%n%wEx";

  public static final String PROPERTY_SOURCE_NAME = "shadhinpayLoggingDefaults";

  public static class TraceAwareLoggingPostProcessor implements EnvironmentPostProcessor {

    @Override
    public void postProcessEnvironment(
        ConfigurableEnvironment environment, SpringApplication application) {
      if (environment.getPropertySources().contains(PROPERTY_SOURCE_NAME)) {
        return;
      }
      PropertySource<?> defaults =
          new MapPropertySource(
              PROPERTY_SOURCE_NAME,
              Collections.unmodifiableMap(
                  java.util.Map.of(
                      "logging.pattern.console", CONSOLE_PATTERN,
                      "logging.pattern.file", FILE_PATTERN)));
      environment.getPropertySources().addLast(defaults);
    }
  }
}

package com.shadhinpay.common.observability;

import java.util.UUID;
import java.util.concurrent.Callable;
import org.slf4j.MDC;

public final class TraceIdContextInitializer {

  private TraceIdContextInitializer() {}

  public static String currentTraceId() {
    return MDC.get(TraceIdFilter.MDC_KEY);
  }

  public static void runWithTraceId(Runnable task) {
    runWithTraceId(UUID.randomUUID().toString(), task);
  }

  public static void runWithTraceId(String traceId, Runnable task) {
    String resolved = resolveOrGenerate(traceId);
    String previous = MDC.get(TraceIdFilter.MDC_KEY);
    MDC.put(TraceIdFilter.MDC_KEY, resolved);
    try {
      task.run();
    } finally {
      restore(previous);
    }
  }

  public static <T> T callWithTraceId(Callable<T> task) throws Exception {
    return callWithTraceId(UUID.randomUUID().toString(), task);
  }

  public static <T> T callWithTraceId(String traceId, Callable<T> task) throws Exception {
    String resolved = resolveOrGenerate(traceId);
    String previous = MDC.get(TraceIdFilter.MDC_KEY);
    MDC.put(TraceIdFilter.MDC_KEY, resolved);
    try {
      return task.call();
    } finally {
      restore(previous);
    }
  }

  public static Runnable wrap(Runnable task) {
    String captured = MDC.get(TraceIdFilter.MDC_KEY);
    return () -> {
      String previous = MDC.get(TraceIdFilter.MDC_KEY);
      if (captured != null) {
        MDC.put(TraceIdFilter.MDC_KEY, captured);
      }
      try {
        task.run();
      } finally {
        restore(previous);
      }
    };
  }

  public static <T> Callable<T> wrap(Callable<T> task) {

if (captured != null) {
        MDC.put(TraceIdFilter.MDC_KEY, captured);
      }
      try {
        task.run();
      } finally {
        restore(previous);
      }
    };
  }

  public static <T> Callable<T> wrap(Callable<T> task) {
    String captured = MDC.get(TraceIdFilter.MDC_KEY);
    return () -> {
      String previous = MDC.get(TraceIdFilter.MDC_KEY);
      if (captured != null) {
        MDC.put(TraceIdFilter.MDC_KEY, captured);
      }
      try {
        return task.call();
      } finally {
        restore(previous);
      }
    };
  }

  private static String resolveOrGenerate(String traceId) {
    if (traceId == null || traceId.isBlank()) {
      return UUID.randomUUID().toString();
    }
    try {
      return UUID.fromString(traceId.trim()).toString();
    } catch (IllegalArgumentException e) {
      return UUID.randomUUID().toString();
    }
  }

  private static void restore(String previous) {
    if (previous == null) {
      MDC.remove(TraceIdFilter.MDC_KEY);
    } else {
      MDC.put(TraceIdFilter.MDC_KEY, previous);
    }
  }
}

package com.shadhinpay.common.observability;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.UUID;
import lombok.extern.slf4j.Slf4j;
import org.slf4j.MDC;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

@Slf4j
@Component
@Order(Ordered.HIGHEST_PRECEDENCE + 10)
public class TraceIdFilter extends OncePerRequestFilter {

  public static final String TRACE_ID_HEADER = "X-ShadhinPay-Trace-ID";
  public static final String MDC_KEY = "traceId";

  @Override
  protected void doFilterInternal(
      HttpServletRequest request, HttpServletResponse response, FilterChain chain)
      throws ServletException, IOException {
    String traceId = resolveTraceId(request.getHeader(TRACE_ID_HEADER));
    boolean mdcSet = false;
    try {
      MDC.put(MDC_KEY, traceId);
      mdcSet = true;
    } catch (RuntimeException e) {
      log.warn("Failed to set MDC trace id; continuing without MDC", e);
    }
    response.setHeader(TRACE_ID_HEADER, traceId);
    try {
      chain.doFilter(request, response);
    } finally {
      if (mdcSet) {
        MDC.remove(MDC_KEY);
      }
    }
  }

  private static String resolveTraceId(String headerValue) {
    if (headerValue == null || headerValue.isBlank()) {
      return UUID.randomUUID().toString();
    }
    try {
      return UUID.fromString(headerValue.trim()).toString();
    } catch (IllegalArgumentException e) {
      String fresh = UUID.randomUUID().toString();
      log.warn(
          "Received malformed {} header '{}'; replacing with fresh id {}",
          TRACE_ID_HEADER,
          headerValue,
          fresh);
      return fresh;
    }

}
    try {
      return UUID.fromString(headerValue.trim()).toString();
    } catch (IllegalArgumentException e) {
      String fresh = UUID.randomUUID().toString();
      log.warn(
          "Received malformed {} header '{}'; replacing with fresh id {}",
          TRACE_ID_HEADER,
          headerValue,
          fresh);
      return fresh;
    }
  }
}

package com.shadhinpay.common.observability;

import java.io.IOException;
import okhttp3.Interceptor;
import okhttp3.Request;
import okhttp3.Response;
import org.springframework.http.HttpRequest;
import org.springframework.http.client.ClientHttpRequestExecution;
import org.springframework.http.client.ClientHttpRequestInterceptor;
import org.springframework.http.client.ClientHttpResponse;
import org.springframework.lang.NonNull;

public final class TraceIdPropagator {

  private TraceIdPropagator() {}

  public static Interceptor okHttpInterceptor() {
    return new OkHttpTraceIdInterceptor();
  }

  public static ClientHttpRequestInterceptor clientHttpInterceptor() {
    return new SpringClientTraceIdInterceptor();
  }

  static final class OkHttpTraceIdInterceptor implements Interceptor {
    @Override
    @NonNull
    public Response intercept(@NonNull Chain chain) throws IOException {
      Request original = chain.request();
      String traceId = TraceIdContextInitializer.currentTraceId();
      if (traceId == null || traceId.isBlank()) {
        return chain.proceed(original);
      }
      Request augmented =
          original.newBuilder().header(TraceIdFilter.TRACE_ID_HEADER, traceId).build();
      return chain.proceed(augmented);
    }
  }

  static final class SpringClientTraceIdInterceptor implements ClientHttpRequestInterceptor {
    @Override
    @NonNull
    public ClientHttpResponse intercept(
        @NonNull HttpRequest request,
        @NonNull byte[] body,
        @NonNull ClientHttpRequestExecution execution)
        throws IOException {
      String traceId = TraceIdContextInitializer.currentTraceId();
      if (traceId != null && !traceId.isBlank()) {
        request.getHeaders().set(TraceIdFilter.TRACE_ID_HEADER, traceId);
      }
      return execution.execute(request, body);
    }
  }
}

