 * /v3/api-docs}.
 *
 * <p>The {@code ApiKeyAuth} security scheme is wired as a global default — every endpoint inherits
 * it unless its operation overrides with {@code @SecurityRequirements({})}. The exact tenant-key
 * header semantics are finalised in Phase 1; for now this is a placeholder bearer-token scheme so
 * the frozen contract already shows the auth surface.
 */
@Configuration
public class OpenApiConfig {

  private static final String API_KEY_SCHEME = "ApiKeyAuth";

  @Bean
  public OpenAPI shadhinPayOpenAPI() {
    return new OpenAPI()
        .info(
            new Info()
                .title("ShadhinPay API")
                .version("v1")
                .description(
                    "ShadhinPay backend API — multi-tenant payment platform. All requests require a"
                        + " tenant API key carried in the Authorization header.")
                .contact(
                    new Contact()
                        .name("ShadhinPay Engineering")
                        .email("engineering@shadhinpay.com"))
                .license(new License().name("Proprietary").url("https://shadhinpay.com/license")))
        .components(
            new Components()
                .addSecuritySchemes(
                    API_KEY_SCHEME,
                    new SecurityScheme()
                        .type(SecurityScheme.Type.HTTP)
                        .scheme("bearer")
                        .bearerFormat("API_KEY")
                        .in(SecurityScheme.In.HEADER)
                        .name("Authorization")
                        .description(
                            "Tenant API key. Send as `Authorization: Bearer <api-key>`. "
                                + "Keys are issued per tenant in Phase 1; rotation invalidates "
                                + "previous keys immediately.")))
        .addSecurityItem(new SecurityRequirement().addList(API_KEY_SCHEME));
  }
}

package com.shadhinpay.application.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.web.SecurityFilterChain;

/**
 * Permissive Spring Security configuration used <strong>only</strong> when the {@code openapi}
 * Spring profile is active. This profile is activated by the {@code -Popenapi} Maven profile in
 * {@code shadhinpay-application/pom.xml}, where the {@code spring-boot:start} mojo boots the
 * application solely so that {@code springdoc-openapi-maven-plugin} can scrape {@code /v3/api-docs}
 * and emit {@code target/openapi/openapi.json}.
 *
 * <p>This bean is NEVER active in dev / staging / prod profiles — the real security configuration
 * lands in Phase 1 alongside the tenant API-key middleware.
 */
@Configuration
@Profile("openapi")
public class OpenApiSecurityConfig {

  @Bean
  public SecurityFilterChain openApiSecurityFilterChain(HttpSecurity http) throws Exception {
    http.csrf(csrf -> csrf.disable())
        .sessionManagement(s -> s.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
        .authorizeHttpRequests(auth -> auth.anyRequest().permitAll());
    return http.build();
  }
}

package com.shadhinpay.adapters.support;

import static org.assertj.core.api.Assertions.assertThat;

import com.shadhinpay.adapters.port.Vendor;
import okhttp3.OkHttpClient;
import org.junit.jupiter.api.Test;

class HttpClientFactoryTest {

  @Test
  void each_vendor_gets_distinct_client_instance() {
    HttpClientFactory factory = new HttpClientFactory();

    OkHttpClient bkash = factory.clientFor(Vendor.BKASH);
    OkHttpClient nagad = factory.clientFor(Vendor.NAGAD);
    OkHttpClient stripe = factory.clientFor(Vendor.STRIPE);

    assertThat(bkash).isNotSameAs(nagad);
    assertThat(bkash).isNotSameAs(stripe);
    assertThat(nagad).isNotSameAs(stripe);
  }

  @Test
  void same_vendor_returns_cached_instance() {
    HttpClientFactory factory = new HttpClientFactory();

    OkHttpClient first = factory.clientFor(Vendor.MOCK);
    OkHttpClient second = factory.clientFor(Vendor.MOCK);

    assertThat(first).isSameAs(second);
  }

  @Test
  void clients_use_configured_timeouts() {
    HttpClientFactory factory = new HttpClientFactory();

    OkHttpClient client = factory.clientFor(Vendor.MOCK);

    assertThat(client.connectTimeoutMillis())
        .isEqualTo((int) HttpClientFactory.CONNECT_TIMEOUT.toMillis());
    assertThat(client.readTimeoutMillis())
        .isEqualTo((int) HttpClientFactory.READ_WRITE_TIMEOUT.toMillis());
    assertThat(client.writeTimeoutMillis())
        .isEqualTo((int) HttpClientFactory.READ_WRITE_TIMEOUT.toMillis());
  }
}

