@org.springframework.modulith.ApplicationModule(
    displayName = "Adapters",
    allowedDependencies = {"common"})
package com.shadhinpay.adapters;

package com.shadhinpay.adapters.support;

import com.shadhinpay.adapters.port.Vendor;
import com.shadhinpay.common.observability.TraceIdPropagator;
import java.time.Duration;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import okhttp3.ConnectionPool;
import okhttp3.OkHttpClient;
import org.springframework.stereotype.Component;

/**
 * Builds and caches one isolated {@link OkHttpClient} per {@link Vendor}.
 *
 * <p>This is the only place in the adapters module that constructs HTTP clients. Per-vendor
 * isolation prevents a slow / hung vendor from exhausting another vendor's connection pool — an
 * explicit non-functional requirement in {@code DOCS/features/adapters/PRD.md} §5.
 *
 * <p>Each client is configured with:
 *
 * <ul>
 *   <li>5 s connect timeout
 *   <li>10 s read / write timeout
 *   <li>50-connection pool with 5-minute keep-alive
 *   <li>{@link TraceIdPropagator#okHttpInterceptor()} so outbound calls carry the inbound request's
 *       trace id for end-to-end log correlation
 * </ul>
 */
@Component
public class HttpClientFactory {

  static final Duration CONNECT_TIMEOUT = Duration.ofSeconds(5);
  static final Duration READ_WRITE_TIMEOUT = Duration.ofSeconds(10);
  static final int MAX_CONNECTIONS = 50;
  static final Duration KEEP_ALIVE = Duration.ofMinutes(5);

  private final ConcurrentMap<Vendor, OkHttpClient> clients = new ConcurrentHashMap<>();

  /**
   * Returns the (cached) {@link OkHttpClient} for {@code vendor}, creating it on first call.
   *
   * @param vendor target vendor
   * @return isolated client for {@code vendor}
   */
  public OkHttpClient clientFor(Vendor vendor) {
    Objects.requireNonNull(vendor, "vendor must not be null");
    return clients.computeIfAbsent(vendor, ignored -> buildClient());
  }

  private OkHttpClient buildClient() {
    return new OkHttpClient.Builder()
        .connectTimeout(CONNECT_TIMEOUT)
        .readTimeout(READ_WRITE_TIMEOUT)
        .writeTimeout(READ_WRITE_TIMEOUT)
        .connectionPool(
            new ConnectionPool(
                MAX_CONNECTIONS, KEEP_ALIVE.toMinutes(), java.util.concurrent.TimeUnit.MINUTES))
        .addInterceptor(TraceIdPropagator.okHttpInterceptor())
        .build();

}

  private OkHttpClient buildClient() {
    return new OkHttpClient.Builder()
        .connectTimeout(CONNECT_TIMEOUT)
        .readTimeout(READ_WRITE_TIMEOUT)
        .writeTimeout(READ_WRITE_TIMEOUT)
        .connectionPool(
            new ConnectionPool(
                MAX_CONNECTIONS, KEEP_ALIVE.toMinutes(), java.util.concurrent.TimeUnit.MINUTES))
        .addInterceptor(TraceIdPropagator.okHttpInterceptor())
        .build();
  }
}

package com.shadhinpay.adapters.support;

import com.shadhinpay.adapters.port.Vendor;
import com.shadhinpay.adapters.port.VendorCredentials;
import org.springframework.stereotype.Component;

/**
 * Placeholder {@link TokenService} active in Phase 1 Wave A — only the {@code MockAdapter} (which
 * does not need vendor tokens) is in play, so any caller is a programmer error. The real
 * Redis-backed implementation arrives in Wave C and will replace this bean.
 */
@Component
public class NoopTokenService implements TokenService {

  @Override
  public String getToken(Vendor vendor, VendorCredentials creds) {
    throw new UnsupportedOperationException(
        "TokenService is not yet wired up; Wave-C adapters will provide a real implementation. "
            + "Vendor="
            + vendor);
  }
}

/**
 * Cross-cutting infrastructure shared by every concrete adapter: provider registry, isolated HTTP
 * client factory, and the (deferred) token service.
 */
@org.springframework.modulith.NamedInterface("support")
package com.shadhinpay.adapters.support;

package com.shadhinpay.adapters.support;

import com.shadhinpay.adapters.error.MfsAdapterException;
import com.shadhinpay.adapters.port.PaymentProvider;
import com.shadhinpay.adapters.port.Vendor;
import java.util.List;
import java.util.Objects;
import org.springframework.stereotype.Component;

/**
 * Spring-managed registry that resolves a {@link Vendor} to the unique {@link PaymentProvider} bean
 * that handles it. All discovered providers are injected at startup; lookup is O(n) over a short
 * list (one bean per vendor).
 *
 * <p>Throws {@link MfsAdapterException} when no bean reports {@link
 * PaymentProvider#supports(Vendor)} {@code == true} for the requested vendor — i.e. the platform
 * has been asked to dispatch to a vendor it does not yet implement.
 */
@Component
public class PaymentProviderRegistry {

  private final List<PaymentProvider> providers;

  public PaymentProviderRegistry(List<PaymentProvider> providers) {
    this.providers = List.copyOf(Objects.requireNonNull(providers, "providers must not be null"));
  }

  /**
   * Returns the provider that supports {@code vendor}.
   *
   * @param vendor target vendor
   * @return the matching {@link PaymentProvider}
   * @throws MfsAdapterException if no provider supports {@code vendor}
   */
  public PaymentProvider lookup(Vendor vendor) {
    Objects.requireNonNull(vendor, "vendor must not be null");
    for (PaymentProvider provider : providers) {
      if (provider.supports(vendor)) {
        return provider;
      }
    }
    throw new MfsAdapterException("No PaymentProvider registered for vendor " + vendor);
  }
}

package com.shadhinpay.adapters.support;

import com.shadhinpay.adapters.port.Vendor;
import com.shadhinpay.adapters.port.VendorCredentials;

/**
 * Centralised vendor session-token cache.
 *
 * <p>Looks up a valid token in Redis for {@code (vendor, credentials)}; on miss or expiry, calls
 * the vendor's auth endpoint, caches the result with a TTL matching vendor policy, and returns the
 * new token. Implementation lands in Phase 1 Wave C alongside the first real adapter; Wave A uses
 * {@link NoopTokenService}.
 */
public interface TokenService {

  /**
   * Returns a valid bearer / session token for the given vendor.
   *
   * @param vendor target vendor
   * @param creds short-lived decrypted credentials used to mint the token if a refresh is needed
   * @return a valid token string
   */
  String getToken(Vendor vendor, VendorCredentials creds);
}

/**
 * Outbound port for MFS adapters.
 *
 * <p>Marked as a Spring Modulith named interface so {@code payment-core} (and other future callers)
 * may depend on the {@link com.shadhinpay.adapters.port.PaymentProvider} contract and its DTOs.
 * Concrete adapter implementations live in private sibling packages (e.g. {@code mock}, {@code
 * bkash}, {@code stripe}) and remain off-limits to outside modules.
 */
@org.springframework.modulith.NamedInterface("port")
package com.shadhinpay.adapters.port;

package com.shadhinpay.adapters.port;

import java.util.Map;
import java.util.Objects;

/**
 * Decrypted vendor credentials, supplied per-call to a {@link PaymentProvider}.
 *
 * <p><b>Lifecycle &amp; security:</b>
 *
 * <ul>
 *   <li>Instances are short-lived: built by {@code payment-core} from a {@code
 *       VendorConfigDescriptor} (provisioning) immediately before the adapter call and discarded
 *       once the call returns.
 *   <li>Never persist, cache, or pass to a logger. The {@link #toString()} override redacts every
 *       value so accidental {@code log.info("creds={}", creds)} calls cannot leak secrets.
 *   <li>The {@code values} map is defensively copied and made immutable so an adapter cannot mutate
 *       the caller's view nor accidentally hold a reference past the request scope.
 * </ul>
 *
 * @param values decrypted key/value pairs (e.g. {@code app_key}, {@code app_secret}, {@code
 *     api_key}); the exact key set is vendor-specific and documented by each adapter
 */
@SuppressWarnings("PMD.UnusedAssignment")
public record VendorCredentials(Map<String, String> values) {

  public VendorCredentials {
    Objects.requireNonNull(values, "values must not be null");
    values = Map.copyOf(values);
  }

  /**
   * Redacted string form: prints only the credential key names and a placeholder, never the actual
   * values. Safe to include in log output and exception messages.
   */
  @Override
  public String toString() {
    StringBuilder sb = new StringBuilder(80);
    sb.append("VendorCredentials{keys=[");
    boolean first = true;
    for (String key : values.keySet()) {
      if (!first) {
        sb.append(", ");
      }
      sb.append(key);
      first = false;
    }
    sb.append("], values=***REDACTED***}");
    return sb.toString();
  }
}

package com.shadhinpay.adapters.port;

import com.shadhinpay.common.money.Money;
import java.util.Map;
import java.util.Objects;
import java.util.UUID;

/**
 * Input to {@link PaymentProvider#initiate(VendorPaymentRequest, VendorCredentials)}.
 *
 * <p>Built by {@code payment-core} after pre-flight (provisioning + risk + quota) and handed off to
 * the selected adapter. Carries no PII beyond what the vendor strictly requires; sensitive customer
 * data is fetched by the vendor on its own redirect page.
 *
 * @param transactionId internal ShadhinPay transaction id; echoed back to the vendor as the
 *     external reference and used to correlate webhooks
 * @param amount transaction amount and currency
 * @param merchantOrderReference merchant-supplied order reference (free-form, &le; 255 chars)
 * @param callbackUrl URL the vendor should redirect the customer back to after checkout
 * @param metadata immutable bag of additional vendor-specific hints (e.g. {@code "channel"}, {@code
 *     "device_id"})
 */
@SuppressWarnings("PMD.UnusedAssignment")
public record VendorPaymentRequest(
    UUID transactionId,
    Money amount,
    String merchantOrderReference,
    String callbackUrl,
    Map<String, String> metadata) {

  public VendorPaymentRequest {
    Objects.requireNonNull(transactionId, "transactionId must not be null");
    Objects.requireNonNull(amount, "amount must not be null");
    Objects.requireNonNull(merchantOrderReference, "merchantOrderReference must not be null");
    Objects.requireNonNull(callbackUrl, "callbackUrl must not be null");
    metadata = metadata == null ? Map.of() : Map.copyOf(metadata);
  }
}

